    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

int options_validate_color(const char *color_str, Color *color) {
    if (strcmp(color_str, "green") == 0) {
        *color = COLOR_GREEN;
        return 1;
    } else if (strcmp(color_str, "red") == 0) {
        *color = COLOR_RED;
        return 1;
    } else if (strcmp(color_str, "blue") == 0) {
        *color = COLOR_BLUE;
        return 1;
    } else if (strcmp(color_str, "white") == 0) {
        *color = COLOR_WHITE;
        return 1;
    } else if (strcmp(color_str, "yellow") == 0) {
        *color = COLOR_YELLOW;
        return 1;
    } else if (strcmp(color_str, "cyan") == 0) {
        *color = COLOR_CYAN;
        return 1;
    } else if (strcmp(color_str, "magenta") == 0) {
        *color = COLOR_MAGENTA;
        return 1;
    } else if (strcmp(color_str, "black") == 0) {
        *color = COLOR_BLACK;
        return 1;
    }
    return 0;
}

int options_validate_delay(int delay) {
    return delay >= MIN_DELAY && delay <= MAX_DELAY;
}

int options_validate_tty(const char *tty) {
    if (tty == NULL || strlen(tty) == 0) {
        return 0;
    }
    struct stat st;
    if (stat(tty, &st) != 0) {
        return 0;
    }
    return 1;
}

int options_validate_message(const char *message) {
    if (message == NULL || strlen(message) == 0) {
        return 0;
    }
    return 1;
}

int options_parse(int argc, char **argv, Options *opts) {
    int i = 1;
    while (i < argc) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0 || strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
            opts->help = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-a") == 0) {
            opts->async_scroll = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-b") == 0) {
            opts->bold_chars = 1;
            opts->no_bold = 0;
            i++;
            continue;
        } else if (strcmp(argv[i], "-B") == 0) {
            opts->all_bold = 1;
            opts->no_bold = 0;
            i++;
            continue;
        } else if (strcmp(argv[i], "-c") == 0) {
            opts->shadows_only = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-f") == 0) {
            opts->force_term = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-l") == 0) {
            opts->linux_mode = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-L") == 0) {
            opts->lock_mode = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-o") == 0) {
            opts->old_scroll = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-n") == 0) {
            opts->no_bold = 1;
            opts->bold_chars = 0;
            opts->all_bold = 0;
            i++;
            continue;
        } else if (strcmp(argv[i], "-s") == 0) {
            opts->screensaver = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-x") == 0) {
            opts->x_window = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-r") == 0) {
            opts->rainbow_mode = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-m") == 0) {
            opts->lambda_mode = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-k") == 0) {
            opts->chars_change = 1;
            i++;
            continue;
        } else if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 >= argc) {
                error_print("Error: -u requires an argument\n");
                return -1;
            }
            opts->delay = atoi(argv[i + 1]);
            if (!options_validate_delay(opts->delay)) {
                error_print("Error: delay must be between 0 and 10\n");
                return -1;
            }
            i += 2;
            continue;
        } else if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 >= argc) {
                error_print("Error: -C requires an argument\n");
                return -1;
            }
            if (!options_validate_color(argv[i + 1], &opts->color)) {
                printf(" Invalid color selection\n");
                printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                return -1;
            }
            i += 2;
            continue;
        } else if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 >= argc) {
                error_print("Error: -M requires an argument\n");
                return -1;
            }
            strncpy(opts->message, argv[i + 1], MAX_MESSAGE_LEN - 1);
            opts->message[MAX_MESSAGE_LEN - 1] = '\0';
            opts->message_set = 1;
            i += 2;
            continue;
        } else if (strcmp(argv[i], "-t") == 0) {
