                return -1;
            }
            strncpy(opts->tty, argv[i + 1], MAX_TTY_LEN - 1);
            opts->tty[MAX_TTY_LEN - 1] = '\0';
            opts->tty_set = 1;
            i += 2;
            continue;
        } else {
            options_print_usage(argv[0]);
            return -1;
        }
    }
    return 0;
}
